        uint8_t TEMP4[3];          /* $001B */
        uint8_t PLAYR;             /* $001E  PLAYER NUMBER (0 OR 1) */
        uint8_t PLAYR2;            /* $001F  PLAYER NUMBER *2 (0 OR 2) */
        uint8_t PLAYR3;            /* $0020  PLAYER NUMBER *3 (0 OR 3) */
        uint8_t LPLAYR;            /* $0021  THE VALUE OF NPLAYR FOR LAST GAME */
        uint8_t NPLAYR;            /* $0022  NUMBER OF PLAYERS (1 OR 2)(0=END OF GAME)(-1=UPDATE HIGH SCORES) */
        uint8_t HSCORE[30];        /* $0023  HIGH SCORES (LSB,MSB) */
        uint8_t UPDINT;            /* $0041  0,1, OR 2 TO INDICATE WHICH INITIAL IS BEING SELECTED */
        uint8_t UPDFLG[2];         /* $0042  POSITIVE MEANS THIS PLAYER HAS SET NEW HIGH SCORE */
