        uint8_t SCORE[6];          /* $0062  PLAYER 1 AND 2 SCORES (LSB1,MSB1,LSB2,MSB2) */
        uint8_t PLATEU[6];         /* $0068  BONUS LEVEL ACCUMULATORS */
