        uint8_t HITS[2];           /* $006F  LIFE COUNTERS (PLAYER 1 / PLAYER 2) */
        uint8_t CHIST[2];          /* $0071  COLLISION HISTORY REGISTERS */
        uint8_t SHDON;             /* $0073 */
        uint8_t GDELAY;            /* $0074  DELAY BEFORE STARTING GAME */
        uint8_t SYNC;              /* $0075  FRAME COUNTER SYNC */
        uint8_t FRAME[2];          /* $0076  FRAME COUNTER */
        uint8_t INTCT;             /* $0078  INTERRUPT COUNTER  orig. $INTCT; */
        uint8_t ANGLE[2];          /* $0079  ANGLE OF ROTATIONS */
        uint8_t LASTSW;            /* $007B  LAST SWITCH READING */
        uint8_t XINCL;             /* $007C  SHIPS LSB FOR X INCREMENT */
        uint8_t YINCL;             /* $007D  SHIPS LSB FOR Y INCREMENT */
        uint8_t SND3;              /* $007E  SOUND FLAGS */
        uint8_t LEXPSND;           /* $007F  LAST VALUE FOR EXPLOSION SOUND (SEE EXPSND) */
        uint8_t LSND1;             /* $0080  LAST VALUE FOR SHIP FIRE SOUND (SEE SHPFIR) */
        uint8_t LSND2;             /* $0081  LAST VALUE FOR SAUCER FIRE SOUND (SEE SCRFIR) */
        uint8_t LTHUMP;            /* $0082  LAST VALUE FOR THUMP SOUND (SEE THUMP) */
        uint8_t THUMP1;            /* $0083  LENGTH OF THUMP SOUNDS */
        uint8_t THUMP2;            /* $0084  LENGTH BETWEEN THUMP SOUNDS */
        uint8_t LOUT1;             /* $0085  LAST VALUE OF OUTPUT LATCH */
        uint8_t ASTERS[4];         /* $0086  ASTERIOD ORIENTATIONS */
        uint8_t PROT[4];           /* $008A */
        uint8_t TWOCM;             /* $008E */
        uint8_t SBTL;              /* $008F  SHIP BACK TO LIFE INTENSITY FLAG */
        uint8_t CPMTST;            /* $0090  COPYRIGHT MESSAGE TEST FLAG */
        uint8_t CRMERR;            /* $0091  COPYRIGHT MESSAGE ERROR */
        uint8_t HOLE;              /* $0092  FLAG FOR COPYRIGHT TEST */
        uint8_t CRDT;              /* $0093  COIN ROUTINE DEFINITION (SEE COIN65.MAC)  orig. $$CRDT; */
        uint8_t CMODE;             /* $0094  orig. $CMODE; */
        uint8_t LMTIM;             /* $0095  orig. $LMTIM; */
        uint8_t CNCT;              /* $0096  orig. $CNCT; */
        uint8_t CCTIM[3];          /* $0097  orig. $CCTIM; */
        uint8_t PSTSL[3];          /* $009A  orig. $PSTSL; */
        uint8_t CNSTT[3];          /* $009D  orig. $CNSTT; */
        uint8_t BCCNT;             /* $00A0  orig. $BCCNT; */
        uint8_t BC;                /* $00A1  orig. $BC; */
        uint8_t POINT[8];          /* $00A2  POINTER OFFSET INTO DATA TABLES */
        uint8_t CURRENT[8];        /* $00AA  OUTPUT VALUE */
        uint8_t FRAMES[8];         /* $00B2  FRAMES UNTIL NEXT CHANGE */
        uint8_t COUNT[8];          /* $00BA  COUNT OF TOTAL CHANGES */
        uint8_t MCOUNT[8];         /* $00C2  BACKGROUND NOISE */
        uint8_t MPNTR[8];          /* $00CA */
        uint8_t EAX;               /* $00D2  EA ACCESS INDEX */
        uint8_t EABC;              /* $00D3  BYTE COUNTER */
        uint8_t EAFLG;             /* $00D4  EA ACTIVITY FLAG */
        uint8_t EAHSX;             /* $00D5  HI-SCORE ENTRY TO WRITE */
        uint8_t EACS;              /* $00D6  CHECKSUM */
        uint8_t EABAD;             /* $00D7  BAD ENTRY FLAG. */
        uint8_t TRILE[2];          /* $00D8  DIAMOND LAUNCH ENABLE */
        uint8_t BINSCR;            /* $00DA  BINARY SCORE */
        uint8_t PERR[5];           /* $00DB  POKEY ERROR(S) */
        uint8_t CKERR;             /* $00E0  SOMEBODY STOLE THIS PGM IF.NE */
        uint8_t RVELP;             /* $00E1  MINIMUM ROCK VELOCITY+ */
        uint8_t RVELM;             /* $00E2  MINIMUM ROCK VELOCITY- */
        uint8_t HSSND;             /* $00E3  HI-SCORE TABLE REACHED FLAG */
        uint8_t SBTLT;             /* $00E4  SHIP BACK TO LIFE TIMER */
        uint8_t EXPDX[8];          /* $00E5  X VEL OF EXPLOSION PIECE */
        uint8_t EXPDY[8];          /* $00ED  Y VEL OF EXPLOSION PIECE */
        uint8_t EXPANG[8];         /* $00F5  ORIENTATION OF PIECE */
