/* Offsets for the parallel-array object model.  The ROM indexes
 * across these deliberately - 0..24 are rocks, 25 the ship, 26
 * the saucer, 27-28 its torpedoes, 29-32 the ship's - so they are
 * reached through the raw view, not as separate C arrays. */
#define AD_OBJ      0x00   /* $0200 */
#define AD_XINC     0x21   /* $0221 */
#define AD_YINC     0x42   /* $0242 */
#define AD_OBJXH    0x63   /* $0263 */
#define AD_OBJYH    0x84   /* $0284 */
#define AD_OBJXL    0xA5   /* $02A5 */
#define AD_OBJYL    0xC6   /* $02C6 */

#define AD_NOBJ      25   /* rocks; DSTDEC.MAC NOBJ */
#define AD_NSPCLS     7   /* special rocks; DSTDEC.MAC NSPCLS */
#define AD_SLOTS     33   /* rocks + ship + saucer + 6 torpedoes */
#define AD_SHIP      25
#define AD_SAUCER    26
#define AD_SAUTP     27   /* .. 28 */
#define AD_SHPTP     29   /* .. 32 */

